cd /workspace && python3 - <<'PY'
import json,subprocess
from public_sanity import check_response,strict_loads
fixtures=json.load(open('examples/checks.json'))
for f in fixtures:
 p=subprocess.run(['python3','run.py'],input=f['input'].encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 print(f['name'],'rc',p.returncode,'err',p.stderr.decode())
 if f.get('invalid'):
  resp=strict_loads(p.stdout)
 else:
  resp=strict_loads(p.stdout)
 try:
  check_response(f,resp);print(' PASS')
 except Exception as e:
  print(' FAIL',e,resp)
